@dataclass
class Options:
    n_value: str = "2"
    top: int = 50
    combi: int = 2
    rep: int = 3
    wpm_threshold: int = 40
    acc_threshold: int = 94
    emu_in: str = ""
    emu_out: str = ""
    show_ortho: bool = False
    no_keyboard: bool = False
    cat: bool = False


@dataclass
