    lesson_number: int = 1
    successes: int = 0
    failures: int = 0
    last_wpm: int = 0
    last_acc: int = 0
    avg_wpm: int = 0
    avg_acc: int = 0


class ParseExit(Exception):
    def __init__(self, code: int, text: str) -> None:
        super().__init__(text)
        self.code = code
        self.text = text


class TTYUnavailable(Exception):
    pass


def round_half_up(value: float) -> int:
    if value <= 0:
        return 0
    return int(value + 0.5)


def basename() -> str:
    return os.path.basename(sys.argv[0]) or "executable"


def help_text() -> str:
    return HELP_TEXT.format(prog=basename())


def unexpected_argument(arg: str) -> ParseExit:
    return ParseExit(
        2,
        f"error: unexpected argument '{arg}' found\n\nUsage: {basename()} [OPTIONS]\n\nFor more information, try '--help'.\n",
    )


def invalid_value(arg: str, canonical: str) -> ParseExit:
    return ParseExit(
        2,
        f"error: invalid value '{arg}' for '{canonical}': invalid digit found in string\n\nFor more information, try '--help'.\n",
    )


def invalid_range(name: str, lower: int, upper: int) -> ParseExit:
    return ParseExit(1, f"Invalid argument for {name}. Use a number between {lower} and {upper}.\n")


def parse_int_option(raw: str, canonical: str, name: str, lower: int, upper: int) -> int:
    try:
        value = int(raw)
    except ValueError as exc:
        raise invalid_value(raw, canonical) from exc
    if value < lower or value > upper:
        raise invalid_range(name, lower, upper)
    return value


def parse_args(argv: Sequence[str]) -> Options:
    opts = Options()
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg in ("-h", "--help"):
            raise ParseExit(0, help_text())
        if arg in ("-n", "--n"):
            i += 1
            if i >= len(argv):
                raise ParseExit(2, f"error: a value is required for '{arg} <2|3|4|w|file>' but none was supplied\n")
            opts.n_value = argv[i]
        elif arg in ("-t", "--top"):
            i += 1
            if i >= len(argv):
                raise ParseExit(2, "error: a value is required for '--top <1-200>' but none was supplied\n")
            if argv[i].startswith("-"):
                raise unexpected_argument(argv[i])
            opts.top = parse_int_option(argv[i], "--top <1-200>", "top", 1, 200)
        elif arg in ("-c", "--combi"):
            i += 1
            if i >= len(argv):
                raise ParseExit(2, "error: a value is required for '--combi <1-200>' but none was supplied\n")
            if argv[i].startswith("-"):
                raise unexpected_argument(argv[i])
            opts.combi = parse_int_option(argv[i], "--combi <1-200>", "combi", 1, 200)
        elif arg in ("-r", "--rep"):
            i += 1
            if i >= len(argv):
                raise ParseExit(2, "error: a value is required for '--rep <number>' but none was supplied\n")
            if argv[i].startswith("-"):
                raise unexpected_argument(argv[i])
            opts.rep = parse_int_option(argv[i], "--rep <number>", "rep", 1, 200)
        elif arg in ("-w", "--wpm"):
            i += 1
            if i >= len(argv):
                raise ParseExit(2, "error: a value is required for '--wpm <number>' but none was supplied\n")
            if argv[i].startswith("-"):
                raise unexpected_argument(argv[i])
            opts.wpm_threshold = parse_int_option(argv[i], "--wpm <number>", "wpm", 1, 200)
        elif arg in ("-a", "--acc"):
            i += 1
            if i >= len(argv):
                raise ParseExit(2, "error: a value is required for '--acc <0-100>' but none was supplied\n")
            if argv[i].startswith("-"):
                raise unexpected_argument(argv[i])
            opts.acc_threshold = parse_int_option(argv[i], "--acc <0-100>", "acc", 0, 100)
        elif arg == "--emu-in":
            i += 1
            if i >= len(argv):
                raise ParseExit(2, "error: a value is required for '--emu-in <layout>' but none was supplied\n")
            opts.emu_in = argv[i]
        elif arg == "--emu-out":
            i += 1
            if i >= len(argv):
                raise ParseExit(2, "error: a value is required for '--emu-out <layout>' but none was supplied\n")
            opts.emu_out = argv[i]
        elif arg == "--show-ortho":
            opts.show_ortho = True
        elif arg == "--nokb":
            opts.no_keyboard = True
        elif arg == "--cat":
            opts.cat = True
        elif arg.startswith("-"):
            raise unexpected_argument(arg)
        else:
            raise unexpected_argument(arg)
        i += 1

    if bool(opts.emu_in) != bool(opts.emu_out):
        raise ParseExit(1, "You need to specify both emu_in and emu_out.\n")
    return opts


def load_pool(opts: Options) -> List[str]:
    if opts.n_value == "2":
        base = BIGRAMS
    elif opts.n_value == "3":
        base = TRIGRAMS
    elif opts.n_value == "4":
        base = TETRAGRAMS
    elif opts.n_value == "w":
        base = WORDS
    else:
        path = opts.n_value
        if not os.path.exists(path):
            raise ParseExit(1, f"File not found: {path}\n")
        text = open(path, "r", encoding="utf-8").read()
        base = [part.strip() for part in text.split(",") if part.strip()]

    if not base:
        return [""]
    limit = min(opts.top, len(base))
    return list(base[:limit])


def flatten_layout(layout_name: str) -> List[str]:
    layout = LAYOUTS.get(layout_name, LAYOUTS["qwerty"])
    return list(layout["top"]) + list(layout["home"]) + list(layout["bottom"])


def translate_char(ch: str, input_layout: str, output_layout: str) -> str:
    if ch == " " or not ch:
        return ch
    lower = ch.lower()
    source = flatten_layout(input_layout)
    target = flatten_layout(output_layout)
    try:
        index = source.index(lower)
    except ValueError:
        return ch
    mapped = target[index]
    if ch.isalpha() and ch.upper() == ch:
        return mapped.upper()
    return mapped


def border_line() -> str:
    return "│" + ("─" * INNER_WIDTH) + "│"


def top_border() -> str:
    label = " Quit <esc> "
    return "╭" + ("─" * (PANEL_WIDTH - len(label) - 2)) + label + "╮"


def bottom_border() -> str:
    return "╰" + ("─" * INNER_WIDTH) + "╯"


def plain_line(text: str = "") -> str:
    visible = text[:INNER_WIDTH]
    return "│" + visible.ljust(INNER_WIDTH) + "│"


def center_plain(text: str = "") -> str:
    visible = text[:INNER_WIDTH]
    return "│" + visible.center(INNER_WIDTH) + "│"


def center_styled(prefix: str, suffix: str) -> str:
    visible = (prefix + suffix)[:INNER_WIDTH]
    left = max(0, (INNER_WIDTH - len(visible)) // 2)
    right = max(0, INNER_WIDTH - left - len(visible))
    styled = ""
    if left:
        styled += " " * left
    styled += prefix
    if suffix:
        styled += "\x1b[1m" + suffix + "\x1b[0m"
    if right:
        styled += " " * right
    return "│" + styled + "│"


def format_header_line(stats: LessonStats) -> str:
    left = f"    Lesson #{stats.lesson_number}"
    right = f"✔: {stats.successes}, ✘: {stats.failures}    "
    inside = left + (" " * max(1, INNER_WIDTH - len(left) - len(right))) + right
    return "│" + inside[:INNER_WIDTH].ljust(INNER_WIDTH) + "│"


def format_wpm_line(opts: Options, stats: LessonStats) -> str:
    text = (
        f"  need >= {opts.wpm_threshold:>3}WPM,   "
        f"avg. {stats.avg_wpm:>4}WPM,   "
        f"last {stats.last_wpm:>4}WPM"
    )
    return plain_line(text)


def format_acc_line(opts: Options, stats: LessonStats) -> str:
    text = (
        f"  need >= {opts.acc_threshold:>3}% Acc, "
        f"avg. {stats.avg_acc:>4}% Acc, "
        f"last {stats.last_acc:>4}% Acc"
    )
    return plain_line(text)


def keyboard_art(layout_name: str, ortho: bool, cat: bool) -> List[str]:
    layout = LAYOUTS.get(layout_name, LAYOUTS["qwerty"])
    top = list(layout["top"])
    home = list(layout["home"])
    bottom = list(layout["bottom"])

    if ortho:
        home_cells = home + ["△"]
        bottom_cells = bottom + ["△", "△"]
        rows = [
            "┌" + "┬".join(["───"] * 12) + "┐",
            "│ " + " │ ".join(top) + " │",
            "├" + "┼".join(["───"] * 12) + "┤",
            "│ " + " │ ".join(home_cells) + " │",
            "├" + "┼".join(["───"] * 12) + "┤",
            "│ " + " │ ".join(bottom_cells) + " │",
            "└" + "┴".join(["───"] * 12) + "┘",
        ]
    else:
        rows = [
            "┌" + "┬".join(["───"] * 12) + "┐",
            "│ " + " │ ".join(top) + " │",
            "└┬" + "┴┬".join(["───"] * 11) + "┴┬──┘",
            " │ " + " │ ".join(home) + " │",
            " └┬" + "┴┬".join(["───"] * 10) + "┴┬──┘",
            "  │ " + " │ ".join(bottom) + " │",
            "  └" + "┴".join(["───"] * 10) + "┘",
        ]

    if not cat:
        return [line.center(INNER_WIDTH) for line in rows]

    left_pad = 4 if ortho else 4
    return [(" " * left_pad + line).ljust(INNER_WIDTH) for line in rows]


def overlay(base: str, start: int, text: str) -> str:
    if start >= INNER_WIDTH:
        return base
    chars = list(base[:INNER_WIDTH].ljust(INNER_WIDTH))
    for idx, ch in enumerate(text):
        pos = start + idx
        if 0 <= pos < INNER_WIDTH:
            chars[pos] = ch
    return "".join(chars)


def apply_cat(lines: List[str], has_keyboard: bool) -> None:
    if has_keyboard:
        overlays = {
            10: (58, "/\\_/\\\\"),
            11: (57, ">(•༝• )<"),
            12: (58, "|    \\"),
            13: (59, "|| |  )"),
            14: (59, "ll-l-//"),
            15: (60, "/▔▔▔▔▔▔▔▔||▔▔\\"),
            16: (69, "\\\\"),
            17: (69, "V"),
        }
    else:
        overlays = {
            10: (58, "/\\_/\\\\"),
            11: (57, ">(•༝• )<"),
            12: (58, "|    \\"),
        }
    for row, (col, text) in overlays.items():
        if 0 <= row < len(lines):
            lines[row] = overlay(lines[row], col, text)


def build_panel_lines(
    opts: Options,
    stats: LessonStats,
    prompt: str,
    cursor: int,
    wrong_chars: Dict[int, str],
) -> List[str]:
    has_keyboard = not opts.no_keyboard
    panel_lines: List[str] = []
    panel_lines.append(top_border())
    title = " " * 19 + "\x1b[1mngrrram!\x1b[0m   by winterveil"
    panel_lines.append("│" + title.ljust(INNER_WIDTH) + "│")
    panel_lines.append(border_line())
    panel_lines.append(format_header_line(stats))
    panel_lines.append(border_line())
    panel_lines.append(plain_line())

    visible_prompt = prompt[:INNER_WIDTH]
    prefix = visible_prompt[: min(cursor, len(visible_prompt))]
    suffix = visible_prompt[min(cursor, len(visible_prompt)) :]
    panel_lines.append(center_styled(prefix, suffix))

    error_line = [" "] * len(visible_prompt)
    for idx, ch in wrong_chars.items():
        if 0 <= idx < len(error_line):
            error_line[idx] = ch
    panel_lines.append(center_plain("".join(error_line).rstrip()))

    if has_keyboard:
        panel_lines.extend("│" + line + "│" for line in keyboard_art(opts.emu_out or "qwerty", opts.show_ortho, opts.cat))
    else:
        panel_lines.append(plain_line())

    panel_lines.append(border_line())
    panel_lines.append(format_wpm_line(opts, stats))
    panel_lines.append(format_acc_line(opts, stats))
    panel_lines.append(bottom_border())

    if opts.cat:
        interior = [line[1:-1] for line in panel_lines]
        apply_cat(interior, has_keyboard)
        panel_lines = [panel_lines[i][0] + interior[i] + panel_lines[i][-1] for i in range(len(panel_lines))]
    return panel_lines


def required_size(opts: Options) -> Tuple[int, int]:
    if opts.no_keyboard:
        return (80, 13)
    return (80, 20)


def render_small_message(opts: Options, cols: int, rows: int) -> str:
    min_cols, min_rows = required_size(opts)
    if opts.no_keyboard:
        message_lines = [
            f"Please resize your terminal to at least {min_cols}x{min_rows}.",
            "",
            "<esc> or <ctrl-c> to quit",
        ]
    else:
        message_lines = [
            f"Please resize your terminal to at least {min_cols}x{min_rows},",
            "or consider disabling the keyboard display with --nokb",
            "",
            "<esc> or <ctrl-c> to quit",
        ]
    top_pad = max(0, rows // 2 - len(message_lines))
    out_lines = [""] * top_pad
    for line in message_lines:
        out_lines.append(line.center(cols))
    return "\x1b[2J\x1b[H" + "\n".join(out_lines)


def sample_lesson(pool: Sequence[str], combi: int, rep: int, rng: random.Random) -> str:
    picks = [rng.choice(pool) for _ in range(combi)]
    lesson_parts: List[str] = []
    for _ in range(rep):
        lesson_parts.extend(picks)
    return " ".join(lesson_parts) + " "


def safe_terminal_size(fd: int) -> Tuple[int, int]:
    size = os.get_terminal_size(fd)
    return size.columns, size.lines


def read_key(fd: int, timeout: float = 0.05) -> Optional[str]:
    ready, _, _ = select.select([fd], [], [], timeout)
    if not ready:
        return None
    data = os.read(fd, 32)
    if not data:
        return None
    if data.startswith(b"\x1b"):
        return "\x1b"
    if data in (b"\x7f", b"\x08"):
        return "BACKSPACE"
    if data == b"\x03":
        return "CTRL_C"
    try:
        text = data.decode("utf-8", "ignore")
    except UnicodeDecodeError:
        return None
    return text[0] if text else None


def update_averages(stats: LessonStats, wpm_values: Sequence[int], acc_values: Sequence[int]) -> None:
    stats.avg_wpm = round_half_up(sum(wpm_values) / len(wpm_values)) if wpm_values else 0
    stats.avg_acc = round_half_up(sum(acc_values) / len(acc_values)) if acc_values else 0


def open_tty_or_fail() -> int:
    if not sys.stdin.isatty() or not sys.stdout.isatty():
        os.write(sys.stdout.fileno(), b"\x1b[?1049h")
        raise TTYUnavailable
    return sys.stdin.fileno()


def run_tui(opts: Options, pool: Sequence[str]) -> int:
    fd = open_tty_or_fail()
    old = termios.tcgetattr(fd)
    rng = random.Random()
    stats = LessonStats()
    wpm_values: List[int] = []
    acc_values: List[int] = []

    prompt = sample_lesson(pool, opts.combi, opts.rep, rng)
    wrong_chars: Dict[int, str] = {}
    cursor = 0
    start_time: Optional[float] = None
    total_keys = 0
    mistakes = 0

    tty.setraw(fd)
    os.write(sys.stdout.fileno(), b"\x1b[?1049h\x1b[2J\x1b[H\x1b[?25l")

    try:
        while True:
            cols, rows = safe_terminal_size(fd)
            min_cols, min_rows = required_size(opts)

            if cols < min_cols or rows < min_rows:
                screen = render_small_message(opts, cols, rows)
            else:
                panel = build_panel_lines(opts, stats, prompt, cursor, wrong_chars)
                screen = "\x1b[2J\x1b[H" + "\n".join(panel)
            os.write(sys.stdout.fileno(), screen.encode("utf-8", "replace"))

            key = read_key(fd)
            if key is None:
                continue
            if key in ("\x1b", "CTRL_C"):
                return 0
            if cols < min_cols or rows < min_rows:
                continue
            if key == "BACKSPACE":
                if cursor > 0:
                    cursor -= 1
                    wrong_chars.pop(cursor, None)
                    total_keys += 1
                continue
            if key == "\r" or key == "\n":
                continue
            if key not in string.printable and key != " ":
                continue

            translated = translate_char(key, opts.emu_in or "qwerty", opts.emu_out or "qwerty")
            if cursor >= len(prompt):
                continue
            if start_time is None:
                start_time = time.monotonic()

            total_keys += 1
            expected = prompt[cursor]
            if translated == expected:
                wrong_chars.pop(cursor, None)
            else:
                wrong_chars[cursor] = translated
                mistakes += 1
            cursor += 1

            if cursor == len(prompt) and not wrong_chars:
                elapsed = max(0.000001, time.monotonic() - (start_time or time.monotonic()))
                non_space_chars = sum(1 for ch in prompt if ch != " ")
                words = non_space_chars / 5.0
                wpm = round_half_up((words * 60.0) / elapsed)
                acc = round_half_up(((total_keys - mistakes) * 100.0) / total_keys) if total_keys else 0

                stats.last_wpm = wpm
                stats.last_acc = acc
                wpm_values.append(wpm)
                acc_values.append(acc)
                update_averages(stats, wpm_values, acc_values)
                if wpm >= opts.wpm_threshold and acc >= opts.acc_threshold:
                    stats.successes += 1
                else:
                    stats.failures += 1
                stats.lesson_number += 1

                prompt = sample_lesson(pool, opts.combi, opts.rep, rng)
                wrong_chars = {}
                cursor = 0
                start_time = None
                total_keys = 0
                mistakes = 0
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old)
        os.write(sys.stdout.fileno(), b"\x1b[0m\x1b[?25h\x1b[?1049l")


def main(argv: Sequence[str]) -> int:
    signal.signal(signal.SIGPIPE, signal.SIG_DFL)
    try:
        opts = parse_args(argv)
        pool = load_pool(opts)
        return run_tui(opts, pool)
    except ParseExit as exc:
        sys.stdout.write(exc.text)
        return exc.code
    except TTYUnavailable:
        sys.stdout.write('Error: Os { code: 6, kind: Uncategorized, message: "No such device or address" }\n')
        return 1


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

