fn main() -> io::Result<()> {
    let argv: Vec<String> = env::args().collect();
    let program = program_name(&argv);
    let args = parse_args(&argv[1..], &program);

    if args.emu_in.is_empty() ^ args.emu_out.is_empty() {
        eprintln!("You need to specify both emu_in and emu_out.");
